.sb-wf--normal { min-width: 1360px; height: 100%; }
.sb-wf-row { display: flex; gap: 8px; align-items: center; }
.sb-wf-title { font-size: 12px; font-weight: 700; color: #334155; margin: 0 0 8px; }
.sb-wf-caption { font-size: 10px; color: #64748b; margin: 4px 0 0; line-height: 1.35; }
.sb-wf-subtitle { font-size: 10px; font-weight: 600; color: #64748b; margin: 0 0 6px; text-transform: uppercase; letter-spacing: .04em; }
.sb-wf-text--desc { font-size: 10px; color: #64748b; line-height: 1.6; margin: 0 0 10px; }
.sb-wf-btn--sm { padding: 4px 10px; font-size: 9px; border-radius: 10px; }
.sb-wf-btn--primary { background: #6366f1; border-color: #6366f1; color: #fff; }
.sb-wf-btn--block { display: flex; width: 100%; justify-content: center; padding: 10px; border-radius: 8px; font-size: 11px; }
.sb-wf-badge { display: inline-block; padding: 1px 5px; background: #fef3c7; border: 1px solid #fcd34d; border-radius: 999px; font-size: 8px; font-weight: 700; color: #b45309; }
.sb-wf-badge--dot { width: 14px; height: 14px; background: #fca5a5; border: 1px solid #f87171; border-radius: 50%; font-size: 8px; color: #fff; display: flex; align-items: center; justify-content: center; padding: 0; }
.sb-wf-block--avatar { width: 28px; height: 28px; border-radius: 50%; background: #cbd5e1; border: 2px solid #fff; }
.sb-wf-nav-bottom-item { margin-top: auto; }
.sb-wf--normal .sb-wf-nav-panel { width: 200px; display: flex; flex-direction: column; min-height: 780px; height: 100%; }
.sb-wf--normal .sb-wf-nav-scroll { flex: 1; display: flex; flex-direction: column; }
.sb-wf-normal-main { flex: 1; display: flex; flex-direction: column; min-width: 0; background: #f8fafc; height: 100%; }
.sb-wf-normal-topbar { display: flex; align-items: center; gap: 12px; padding: 10px 20px; border-bottom: 1px solid #e2e8f0; background: #fff; }
.sb-wf-breadcrumb { font-size: 11px; color: #64748b; flex-shrink: 0; white-space: nowrap; }
.sb-wf-breadcrumb strong { color: #334155; font-weight: 600; }
.sb-wf-normal-topbar .sb-wf-search { flex: 1; max-width: 420px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 8px 14px; border: 1px solid #e2e8f0; border-radius: 999px; background: #fafbfc; font-size: 11px; color: #94a3b8; }
.sb-wf-search-kbd { font-size: 9px; padding: 2px 6px; border: 1px solid #e2e8f0; border-radius: 4px; background: #fff; color: #94a3b8; }
.sb-wf-normal-topbar-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; flex-shrink: 0; }
.sb-wf-normal-head { padding: 16px 20px 0; background: #fff; border-bottom: 1px solid #f1f5f9; }
.sb-wf-normal-hero { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.sb-wf-normal-hero .sb-wf-text--h1 { font-size: 18px; margin-bottom: 4px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.sb-wf-normal-badge { display: inline-flex; padding: 3px 8px; border-radius: 999px; background: #ede9fe; border: 1px solid #c4b5fd; font-size: 9px; font-weight: 700; color: #6d28d9; }
.sb-wf-normal-stepper { display: flex; gap: 8px; padding-bottom: 14px; }
.sb-wf-normal-step { flex: 1; border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px 12px; background: #fafbfc; text-align: center; }
.sb-wf-normal-step.is-active { border-color: #6366f1; background: #eef2ff; border-style: solid; }
.sb-wf-normal-step-num { display: inline-flex; width: 20px; height: 20px; border-radius: 50%; background: #e2e8f0; color: #64748b; font-size: 10px; font-weight: 800; align-items: center; justify-content: center; margin-bottom: 4px; }
.sb-wf-normal-step.is-active .sb-wf-normal-step-num { background: #6366f1; color: #fff; }
.sb-wf-normal-step-label { font-size: 10px; font-weight: 700; color: #334155; display: block; }
.sb-wf-normal-step-desc { font-size: 9px; color: #94a3b8; margin-top: 2px; display: block; }
.sb-wf-normal-body { flex: 1; display: flex; gap: 14px; padding: 14px 20px 20px; align-items: flex-start; }
.sb-wf-normal-form-col { flex: 1.2; min-width: 0; display: flex; flex-direction: column; gap: 14px; }
.sb-wf-normal-preview-col { flex: 0 0 280px; }
.sb-wf-normal-side { flex: 0 0 220px; display: flex; flex-direction: column; gap: 12px; }
.sb-wf-form-section { border: 1px solid #e2e8f0; border-radius: 12px; padding: 14px 14px 16px; background: #fff; }
.sb-wf-form-section .sb-wf-section-title { font-size: 12px; font-weight: 700; color: #334155; margin: 0 0 12px; }
.sb-wf-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 14px; }
.sb-wf-form-grid .sb-wf-field--full { grid-column: 1 / -1; }
.sb-wf-field { margin-bottom: 0; }
.sb-wf-field label { display: block; font-size: 10px; font-weight: 600; color: #475569; margin-bottom: 4px; }
.sb-wf-input { display: flex; align-items: center; padding: 8px 12px; border: 1px solid #e2e8f0; border-radius: 8px; background: #fafbfc; font-size: 11px; color: #94a3b8; min-height: 34px; }
.sb-wf-input--select::after { content: ' ▼'; margin-left: auto; font-size: 9px; color: #94a3b8; }
.sb-wf-input--textarea { min-height: 72px; align-items: flex-start; line-height: 1.45; padding: 10px 12px; }
.sb-wf-input--textarea-sm { min-height: 52px; }
.sb-wf-field-foot { display: flex; justify-content: flex-end; font-size: 9px; color: #94a3b8; margin-top: 4px; }
.sb-wf-color-row { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.sb-wf-color-swatch { width: 24px; height: 24px; border-radius: 50%; border: 2px solid #cbd5e1; background: #e2e8f0; flex-shrink: 0; }
.sb-wf-color-swatch.is-active { border-color: #6366f1; box-shadow: 0 0 0 2px #eef2ff; }
.sb-wf-upload-box { border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px 12px; text-align: center; background: #fafbfc; font-size: 10px; color: #94a3b8; line-height: 1.45; }
.sb-wf-tone-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.sb-wf-tone-card { border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px 8px; background: #fff; text-align: center; position: relative; min-height: 72px; }
.sb-wf-tone-card.is-selected { border-color: #6366f1; border-style: solid; background: #faf5ff; }
.sb-wf-tone-card .sb-wf-block--icon { width: 32px; height: 32px; margin: 0 auto 6px; font-size: 14px; }
.sb-wf-tone-card .sb-wf-text { font-size: 9px; font-weight: 700; }
.sb-wf-tone-check { position: absolute; top: 6px; right: 6px; width: 16px; height: 16px; border-radius: 50%; background: #6366f1; color: #fff; font-size: 9px; display: flex; align-items: center; justify-content: center; }
.sb-wf-preview-card { border: 1px solid #e2e8f0; border-radius: 12px; padding: 12px; background: #fff; position: sticky; top: 0; }
.sb-wf-preview-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.sb-wf-preview-head .sb-wf-title { margin: 0; font-size: 11px; }
.sb-wf-preview-frame { min-height: 220px; border: 1px solid #e2e8f0; border-radius: 10px; background: #f1f5f9; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; font-size: 10px; color: #94a3b8; padding: 12px; margin-bottom: 10px; }
.sb-wf-preview-frame::before { content: '✕ PREVIEW'; font-size: 11px; font-weight: 700; color: #64748b; margin-bottom: 6px; }
.sb-wf-preview-controls { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.sb-wf-preview-zoom { display: flex; gap: 4px; align-items: center; }
.sb-wf-preview-zoom .sb-wf-btn { padding: 4px 8px; font-size: 10px; border-radius: 6px; }
.sb-wf-points-card { padding: 12px; border: 1px solid #fde68a; border-radius: 10px; background: #fffbeb; }
.sb-wf-points-card .sb-wf-subtitle { margin: 0 0 4px; font-size: 9px; text-transform: none; color: #92400e; }
.sb-wf-points-card .sb-wf-text { font-size: 14px; font-weight: 800; color: #b45309; }
.sb-wf-side-card { border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px; background: #fff; }
.sb-wf-side-card-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.sb-wf-side-card-head .sb-wf-title { margin: 0; font-size: 11px; }
.sb-wf-side-link { font-size: 9px; color: #6366f1; font-weight: 600; }
.sb-wf-history-list { list-style: none; margin: 0; padding: 0; }
.sb-wf-history-item { display: flex; gap: 8px; padding: 8px 0; border-bottom: 1px dotted #e2e8f0; align-items: flex-start; }
.sb-wf-history-item:last-child { border-bottom: none; }
.sb-wf-history-thumb { width: 36px; height: 36px; flex-shrink: 0; background: #f1f5f9; border: 1px solid #e2e8f0; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 7px; color: #94a3b8; }
.sb-wf-history-thumb::before { content: '✕ THUMB'; }
.sb-wf-history-meta .sb-wf-text { font-size: 10px; font-weight: 600; margin-bottom: 2px; }
.sb-wf-tip-list { list-style: none; margin: 0; padding: 0; }
.sb-wf-tip-list li { display: flex; gap: 8px; padding: 7px 0; font-size: 9px; color: #64748b; line-height: 1.4; border-bottom: 1px dotted #e2e8f0; }
.sb-wf-tip-list li:last-child { border-bottom: none; }
.sb-wf-tip-list .sb-wf-block--icon { width: 20px; height: 20px; font-size: 9px; flex-shrink: 0; }
